#!/usr/bin/env python3
"""Package this owned run's reviewed artifacts; no original binaries included."""
import pathlib,json,hashlib
r=pathlib.Path(__file__).resolve().parent.parent
rid=r.name
base='7c315c103e6eda864f5bd9f3c3736a03b4c1fa7c'
def h(p):return hashlib.sha256((r/p).read_bytes()).hexdigest()
def ev(p):return {'kind':'run-artifact','ref':p,'sha256':h(p)}
def addr(va):return {'kind':'retail-address','ref':'retail i76.exe','address':va}
claims=[
 ('F1-coordinate-map','Original initialized lookup maps serialized ZMAP column/row to positive lattice X/Z, internal +3072 translation, 128-sample local addressing and 5-unit world spacing with low12*0.1f height.','proven','high','artifacts/TERRAIN_COORDINATE_CONTRACT.md',['00493080','00493160','004931A4'],'Static instructions and representative M06/CD M02 execution. Conceptual world placement is distinguished from prior accepted source/view buffer semantics; no full renderer replay.'),
 ('F2-neighbor-continuity','Each bilinear corner resolves its own global lattice location, traversing horizontal/vertical/diagonal page boundaries without duplicated edge samples; controlled repeated references reset local offsets.','proven','high','artifacts/PAGE_CONTINUITY.md',['00493652','004936A5','004936F8','0049373D'],'Retail M06/CD M02 have unique active ordinals; active alias uses an explicitly modified ZMAP. Address ownership does not guarantee equal adjacent heights or slopes.'),
 ('F3-default-and-bounds','The initialized tested image uses a zero default page for valid unmapped grid entries; default class0 differs from rejected world material class5, while direct helper lacks a negative-slot guard.','proven','high','artifacts/PAGE_CONTINUITY.md',['0059C588','00493080','004927B0','00493160'],'No unsafe negative-slot dereference or claim about indirect writes/teardown/full-game default lifetime. Checked reconstruction domain is a proposed safety boundary.'),
 ('F4-native-numerics','Unchanged retail sample/height/class instructions executed on CPU match an independent rational/address model across 668 cases, including staged x87 admission and RC-down row stores.','proven','high','artifacts/NUMERICAL_BEHAVIOR.md',['00493550','0049375D','00493769','00493792'],'Native Linux i386 shim supplies image/grid/default/TER memory; default CW037F only. Not Windows or complete native engine execution; 392 of these cases are world-height queries.'),
 ('F5-emulator-narrowing','Correcting the two FISTP instructions alone does not make Ghidra terrain heights bit-exact; recorded native differences persist while captured addressing agrees.','proven','high','artifacts/NUMERICAL_BEHAVIOR.md',['004935EE','00493608','0049375D','00493769'],'Measured Ghidra12.1.4/native environment. Narrows earlier emulator interpretations, not the accepted static RC-down contract. Detailed deltas are retained rather than hidden as passing parity.'),
 ('F6-bit12-bounded','XORing bit12 in private M06 TER leaves tested native height/class outputs and emulated query normals unchanged; its overall meaning remains unresolved.','proven','high','artifacts/NUMERICAL_BEHAVIOR.md',['004931A8','004927B0','004931C0'],'Bounded negative evidence only. Native normals, complete rendering position replay and all bit12 consumers are untested; no semantic label is assigned.'),
 ('F7-bit12-purpose','The general original purpose of packed TER bit12 remains unresolved.','unresolved','unknown','artifacts/NUMERICAL_BEHAVIOR.md',[],'No global no-effect claim follows from the controlled sampler/normal negative result.')]
findings=[]
for id,claim,status,confidence,report,vas,limits in claims:
 evidence=[ev(report),ev('evidence/coordinate_cases.jsonl'),ev('evidence/results.json')]+[addr(va) for va in vas]
 findings.append({'finding_id':id,'claim':claim,'status':status,'confidence':confidence,'scope':'game','evidence':evidence,'limitations':limits})
(r/'findings.json').write_text(json.dumps({'schema_version':'1.2.0','run_id':rid,'findings':findings},indent=2)+'\n')
ident=json.loads((r/'evidence/input_identities.json').read_text());inputs=[]
for name in ['exe','M06.MSN','M06.TER','M02.MSN','M02.TER','zfs','ISO']:
 d=ident[name];inputs.append({'name':{'exe':'i76.exe','zfs':'I76.ZFS','ISO':'I76_CD1.ISO'}.get(name,name),'kind':'retail-executable' if name=='exe' else 'resource-manifest' if name in ['zfs','ISO'] else 'other','md5':d['md5'],'sha256':d['sha256'],'notes':('CD MISSIONS/M02.MSN privately extracted; installed loose metadata not used in final run.' if name=='M02.MSN' else 'Hash-verified private input; bytes not published. See input ledger and reproduction/service reports for active use.')})
artifacts=[]
for folder in ['artifacts','evidence','scripts']:
 for p in sorted((r/folder).rglob('*')):
  if not p.is_file():continue
  if '__pycache__' in p.parts or p.suffix=='.pyc':continue
  rel=str(p.relative_to(r));artifacts.append({'path':rel,'kind':'script' if folder=='scripts' else 'report' if folder=='artifacts' else 'test-result' if p.name in ['negative_controls.json','policy_validation.json','verification.json'] else 'table','sha256':h(rel),'bytes':p.stat().st_size})
validation=json.loads((r/'validation.json').read_text())
m={'schema_version':'1.2.0','protocol_version':'1.0.5','run_id':rid,'track':'i76exe','topic':'Retail terrain coordinates, neighboring pages and exact sampler arithmetic','base_commit':base,'started_at':'2026-11-06T01:15:34Z','summary':'Research only: M06 and CD M02 addressing/native numeric evidence, explicit default pages, controlled alias/bit12, bounded C++ handoff. No maintained reconstruction/canonical edits.','inputs':inputs,'baselines':[{'version':'Ghidra 12.1.4 / annotated v97','program_name':'i76_mission_v97_verified_names','baseline_id':'i76_mission_v97_verified_names.gzf','baseline_sha256':ident['gzf']['sha256'],'storage_ref':'private licensed researcher storage; see REPRODUCE.md','notes':'Measured private export; disposable read-only import, full executable-section identity checked.'}],'artifacts':artifacts,'validation':validation,'reproducibility':{'status':'complete','script_refs':[{'kind':'script','ref':'scripts/reproduce.py','sha256':h('scripts/reproduce.py')},{'kind':'script','ref':'scripts/verify_coordinates.py','sha256':h('scripts/verify_coordinates.py')},{'kind':'script','ref':'scripts/negative_controls.py','sha256':h('scripts/negative_controls.py')}],'methods':['binary-static PE/Ghidra code equality','original-instruction Ghidra emulation with explicit services','unchanged original instructions on native i386 CPU with supplied environment','independent integer and exact rational arithmetic','authenticated retail M06 and CD M02 corpus','controlled page alias/bit12 and fresh-emulator repeat','negative corruption controls'],'limitations':'Requires private licensed inputs, Ghidra12.1.4/JDK, x86 Linux with i386 execution and local compiler/7z. No full retail Windows execution, native normal verification, unsafe negative-slot reads, nondefault x87 state or global bit12 purpose. Exact final CPU sample/height/class outputs checked; emulator numerical mismatches are diagnostics.'}}
(r/'manifest.json').write_text(json.dumps(m,indent=2)+'\n');print(json.dumps({'artifacts':len(artifacts),'findings':len(findings),'validation':validation}))
